-- Ecological Context: The ecological and/or biogeographic classification of the region from which objects associated with the ObjectGroup were collected, or where an Event took place.
CREATE TABLE ltc_dp_collapsed.ecological_context (
    "ecologicalContext_pk" text NOT NULL,
    "event_fk" text,
    "objectGroup_fk" text,
    "biogeographicRealm" text,
    "biome" text,
    "biomeType" text,
    "bioregion" text,
    "ecoregion" text,
    "ecosystem" text,
    "habitat" text,
    CONSTRAINT ecological_context_pkey PRIMARY KEY ("ecologicalContext_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.ecological_context IS 'The ecological and/or biogeographic classification of the region from which objects associated with the ObjectGroup were collected, or where an Event took place. [http://rs.tdwg.org/ltc/terms/EcologicalContext]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."ecologicalContext_pk" IS 'A unique identifier for an ltc:EcologicalContext. [http://example.com/term-pending/ecologicalContextID]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."event_fk" IS 'An identifier for an ltc:Event. [http://rs.tdwg.org/ltc/terms/hasEcologicalContext]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasEcologicalContext]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."biogeographicRealm" IS 'The broadest biogeographic division of Earth''s land and marine surface, based on distributional patterns of terrestrial and marine organisms. [http://rs.tdwg.org/ltc/terms/biogeographicRealm]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."biome" IS 'A biogeographical unit consisting of a biological community that has formed in response to the physical environment in which they are found and a shared regional climate. [http://rs.tdwg.org/ltc/terms/biome]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."biomeType" IS 'A top level classification of the type of biome from which objects were collected or where an event took place. [http://rs.tdwg.org/ltc/terms/biomeType]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."bioregion" IS 'An ecologically and geographically defined area that is smaller than a biogeographic realm, but larger than an ecoregion or an ecosystem. [http://rs.tdwg.org/ltc/terms/bioregion]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."ecoregion" IS 'An ecologically and geographically defined area that is smaller than a bioregion, which in turn is smaller than a biogeographic realm. Ecoregions cover relatively large areas of land or water, and contain characteristic, geographically distinct assemblages of natural communities and species. [http://rs.tdwg.org/ltc/terms/ecoregion]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."ecosystem" IS 'A specific kind of ecological classification that considers all four elements of the definition of ecosystems: a biotic component, an abiotic complex, the interactions between and within them, and the physical space that they occupy. [http://rs.tdwg.org/ltc/terms/ecosystem]';
COMMENT ON COLUMN ltc_dp_collapsed.ecological_context."habitat" IS 'A description of the type of environment in which an organism lives. [http://rs.tdwg.org/ltc/terms/habitat]';

