COMMENT ON COLUMN ltc_dp_collapsed.identifier."collectionStatusHistory_fk" IS 'An identifier for an ltc:CollectionStatusHistory. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."contactDetail_fk" IS 'An identifier for an ltc:ContactDetail. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."ecologicalContext_fk" IS 'An identifier for an ltc:EcologicalContext. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."event_fk" IS 'An identifier for an ltc:Event. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."geographicContext_fk" IS 'An identifier for an ltc:GeographicContext. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."geologicalContext_fk" IS 'An identifier for an ltc:GeologicalContext. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."latimerCoreScheme_fk" IS 'An identifier for an ltc:LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."measurementOrFact_fk" IS 'An identifier for an ltc:MeasurementOrFact. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."objectClassification_fk" IS 'An identifier for an ltc:ObjectClassification. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."organisationalUnit_fk" IS 'An identifier for an ltc:OrganisationalUnit. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."person_fk" IS 'An identifier for an ltc:Person. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."personRole_fk" IS 'An identifier for an ltc:PersonRole. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."recordLevel_fk" IS 'An identifier for an ltc:RecordLevel. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."reference_fk" IS 'An identifier for an ltc:Reference. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."resourceRelationship_fk" IS 'An identifier for an ltc:ResourceRelationship. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."role_fk" IS 'An identifier for an ltc:Role. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."schemeMeasurementOrFact_fk" IS 'An identifier for an ltc:SchemeMeasurementOrFact. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."schemeTerm_fk" IS 'An identifier for an ltc:SchemeTerm. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."storageLocation_fk" IS 'An identifier for an ltc:StorageLocation. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."taxon_fk" IS 'An identifier for an ltc:Taxon. [http://rs.tdwg.org/ltc/terms/hasIdentifier]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."identifierSource" IS 'The source or creator of the identifier. [http://rs.tdwg.org/ltc/terms/identifierSource]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."identifierType" IS 'The type and format of the value in the identifier field. [http://rs.tdwg.org/ltc/terms/identifierType]';
COMMENT ON COLUMN ltc_dp_collapsed.identifier."identifierValue" IS 'A textual or numeric identifier, acronym or IRI that provides an unambiguous reference for an entity within a given context. [http://rs.tdwg.org/ltc/terms/identifierValue]';

-- Latimer Core Scheme: A grouping of multiple ObjectGroups for a particular use case, purpose or implementation.
CREATE TABLE ltc_dp_collapsed.latimer_core_scheme (
    "latimerCoreScheme_pk" text NOT NULL,
    "basisOfScheme" text,
    "isDistinctObjects" boolean NOT NULL,
    "schemeName" text NOT NULL,
    CONSTRAINT latimer_core_scheme_pkey PRIMARY KEY ("latimerCoreScheme_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.latimer_core_scheme IS 'A grouping of multiple ObjectGroups for a particular use case, purpose or implementation. [http://rs.tdwg.org/ltc/terms/LatimerCoreScheme]';
COMMENT ON COLUMN ltc_dp_collapsed.latimer_core_scheme."latimerCoreScheme_pk" IS 'A unique identifier for an ltc:LatimerCoreScheme. [http://example.com/term-pending/latimerCoreSchemeID]';
COMMENT ON COLUMN ltc_dp_collapsed.latimer_core_scheme."basisOfScheme" IS 'A summary of the basis or purpose for the LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/basisOfScheme]';
COMMENT ON COLUMN ltc_dp_collapsed.latimer_core_scheme."isDistinctObjects" IS 'A flag to designate whether a physical object may be described by more than one ObjectGroup within the LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/isDistinctObjects]';
COMMENT ON COLUMN ltc_dp_collapsed.latimer_core_scheme."schemeName" IS 'A short descriptive name given to the LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/schemeName]';

-- Measurement or Fact: A measurement of or fact about a class within the standard, or a relationship between the ObjectGroup and an associated class.
CREATE TABLE ltc_dp_collapsed.measurement_or_fact (
    "measurementOrFact_pk" text NOT NULL,
    "chronometricAge_fk" text,
    "collectionStatusHistory_fk" text,
    "ecologicalContext_fk" text,
    "event_fk" text,
    "geographicContext_fk" text,
    "geologicalContext_fk" text,
    "objectClassification_fk" text,
    "objectGroup_fk" text,
    "organisationalUnit_fk" text,
    "person_fk" text,
    "personRole_fk" text,
    "resourceRelationship_fk" text,
    "storageLocation_fk" text,
    "taxon_fk" text,
    "temporalCoverage_fk" text,
    "measurementAccuracy" text,
    "measurementDerivation" text,
    "measurementFactText" text,
    "measurementMethod" text,
    "measurementRemarks" text,
    "measurementType" text,
    "measurementUnit" text,
    "measurementValue" numeric,
    CONSTRAINT measurement_or_fact_pkey PRIMARY KEY ("measurementOrFact_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.measurement_or_fact IS 'A measurement of or fact about a class within the standard, or a relationship between the ObjectGroup and an associated class. [http://rs.tdwg.org/ltc/terms/MeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementOrFact_pk" IS 'A unique identifier for an ltc:MeasurementOrFact. [http://example.com/term-pending/measurementOrFactID]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."chronometricAge_fk" IS 'An identifier for an ltc:ChronometricAge. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."collectionStatusHistory_fk" IS 'An identifier for an ltc:CollectionStatusHistory. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."ecologicalContext_fk" IS 'An identifier for an ltc:EcologicalContext. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."event_fk" IS 'An identifier for an ltc:Event. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."geographicContext_fk" IS 'An identifier for an ltc:GeographicContext. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."geologicalContext_fk" IS 'An identifier for an ltc:GeologicalContext. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."objectClassification_fk" IS 'An identifier for an ltc:ObjectClassification. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."organisationalUnit_fk" IS 'An identifier for an ltc:OrganisationalUnit. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."person_fk" IS 'An identifier for an ltc:Person. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."personRole_fk" IS 'An identifier for an ltc:PersonRole. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."resourceRelationship_fk" IS 'An identifier for an ltc:ResourceRelationship. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."storageLocation_fk" IS 'An identifier for an ltc:StorageLocation. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."taxon_fk" IS 'An identifier for an ltc:Taxon. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."temporalCoverage_fk" IS 'An identifier for an ltc:TemporalCoverage. [http://rs.tdwg.org/ltc/terms/hasMeasurementOrFact]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementAccuracy" IS 'The description of the potential error associated with the measurementValue. [http://rs.tdwg.org/dwc/terms/measurementAccuracy]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementDerivation" IS 'An indicator as to whether the measurement, fact, characteristic, or assertion being applied to the collection was derived from reported figures or aggregated/calculated from underlying data. [http://rs.tdwg.org/ltc/terms/measurementDerivation]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementFactText" IS 'The value of the qualitative fact, characteristic, or assertion being made about the collection. [http://rs.tdwg.org/ltc/terms/measurementFactText]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementMethod" IS 'A description of or reference to (publication, IRI) the method or protocol used to determine the measurement, fact, characteristic, or assertion. [http://rs.tdwg.org/dwc/terms/measurementMethod]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementRemarks" IS 'Comments or notes accompanying the MeasurementOrFact. [http://rs.tdwg.org/dwc/terms/measurementRemarks]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementType" IS 'The nature of the measurement, fact, characteristic, or assertion. [http://rs.tdwg.org/dwc/terms/measurementType]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementUnit" IS 'The units associated with the measurementValue. [http://rs.tdwg.org/dwc/terms/measurementUnit]';
COMMENT ON COLUMN ltc_dp_collapsed.measurement_or_fact."measurementValue" IS 'The value of the measurement, fact, characteristic, or assertion. [http://rs.tdwg.org/dwc/terms/measurementValue]';

-- Object Classification: An informal classification of the type of objects within the ObjectGroup, using a hierarchical structure.
CREATE TABLE ltc_dp_collapsed.object_classification (
    "objectClassification_pk" text NOT NULL,
    "objectGroup_fk" text NOT NULL,
    "parentObjectClassification_fk" text NOT NULL,
    "isTopParent" boolean,
    "objectClassificationLevel" text,
    "objectClassificationName" text NOT NULL,
    CONSTRAINT object_classification_pkey PRIMARY KEY ("objectClassification_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.object_classification IS 'An informal classification of the type of objects within the ObjectGroup, using a hierarchical structure. [http://rs.tdwg.org/ltc/terms/ObjectClassification]';
COMMENT ON COLUMN ltc_dp_collapsed.object_classification."objectClassification_pk" IS 'A unique identifier for an ltc:ObjectClassification. [http://example.com/term-pending/objectClassificationID]';
COMMENT ON COLUMN ltc_dp_collapsed.object_classification."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasObjectClassification]';
COMMENT ON COLUMN ltc_dp_collapsed.object_classification."parentObjectClassification_fk" IS 'An identifier for an ltc:ObjectClassification. [http://example.com/term-pending/hasParentObjectClassification]';
COMMENT ON COLUMN ltc_dp_collapsed.object_classification."isTopParent" IS 'A flag to indicate that the current instance of ObjectClassification is at the top of the hierarchy represented by multiple nested instances of the class. [http://rs.tdwg.org/ltc/terms/isTopParent]';
COMMENT ON COLUMN ltc_dp_collapsed.object_classification."objectClassificationLevel" IS 'The level of the ObjectClassification in the hierarchy. [http://rs.tdwg.org/ltc/terms/objectClassificationLevel]';
COMMENT ON COLUMN ltc_dp_collapsed.object_classification."objectClassificationName" IS 'A short title describing this ObjectClassification as a class, unit or grouping. [http://rs.tdwg.org/ltc/terms/objectClassificationName]';

-- Object Group: An intentionally grouped set of objects with one or more common characteristics.
CREATE TABLE ltc_dp_collapsed.object_group (
    "objectGroup_pk" text NOT NULL,
    "latimerCoreScheme_fk" text,
    "recordLevel_fk" text,
    "alternativeCollectionName" text[],
    "baseTypeOfObjectGroup" text[] NOT NULL,
    "collectionManagementSystem" text[],
    "collectionName" text,
    "conditionsOfAccess" text[],
    "degreeOfEstablishment" text[],
    "description" text,
    "discipline" text[],
    "isCurrentCollection" boolean,
    "isKnownToContainTypes" boolean,
    "material" text[],
    "objectType" text[],
    "period" text[],
    "preparationType" text[],
    "preservationMethod" text[],
    "preservationMode" text[],
    "typeOfObjectGroup" text[],
    CONSTRAINT object_group_pkey PRIMARY KEY ("objectGroup_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.object_group IS 'An intentionally grouped set of objects with one or more common characteristics. [http://rs.tdwg.org/ltc/terms/ObjectGroup]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."objectGroup_pk" IS 'A unique identifier for an ltc:ObjectGroup. [http://example.com/term-pending/objectGroupID]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."latimerCoreScheme_fk" IS 'An identifier for an ltc:LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/hasObjectGroup]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."recordLevel_fk" IS 'An identifier for an ltc:RecordLevel. [http://rs.tdwg.org/ltc/terms/hasObjectGroup]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."alternativeCollectionName" IS 'One or more short titles different to the one given in ObjectGroup.collectionName used to summarise the collection objects contained within the ObjectGroup. [http://rs.tdwg.org/ltc/terms/alternativeCollectionName]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."baseTypeOfObjectGroup" IS 'High-level terms describing the fundamental nature of objects in the ObjectGroup. [http://rs.tdwg.org/ltc/terms/baseTypeOfObjectGroup]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."collectionManagementSystem" IS 'The collection management system which is used to hold and manage the primary data for the objects contained within the ObjectGroup. [http://rs.tdwg.org/ltc/terms/collectionManagementSystem]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."collectionName" IS 'A short title that summarises the collection objects contained within the ObjectGroup. [http://rs.tdwg.org/ltc/terms/collectionName]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."conditionsOfAccess" IS 'Information about who can access the collection being described or an indication of its security status. [http://rs.tdwg.org/ltc/terms/conditionsOfAccess]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."degreeOfEstablishment" IS 'The degree to which an Organism survives, reproduces, and expands its range at the given place and time. [http://rs.tdwg.org/dwc/terms/degreeOfEstablishment]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."description" IS 'A free text description or narrative about the collection. [http://rs.tdwg.org/ltc/terms/description]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."discipline" IS 'A high level classification of the scientific discipline to which the objects within the collection belong or are related. [http://rs.tdwg.org/ltc/terms/discipline]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."isCurrentCollection" IS 'A flag to indicate whether the collection still exists as a single entity. [http://rs.tdwg.org/ltc/terms/isCurrentCollection]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."isKnownToContainTypes" IS 'Flag property to indicate that the collection is known to include type specimens. [http://rs.tdwg.org/ltc/terms/isKnownToContainTypes]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."material" IS 'Material denotes the raw substance(s) from which the object is formed, in whole or in part. [http://rs.tdwg.org/ltc/terms/material]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."objectType" IS 'High-level terms for the classification of curated objects. [http://rs.tdwg.org/ltc/terms/objectType]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."period" IS 'Used to describe prehistoric or historic periods. [http://rs.tdwg.org/ltc/terms/period]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."preparationType" IS 'A term used to classify or describe an object that indicates the actions that have been taken upon it and/or the processes it has been put through to prepare it for scientific use or study. [http://rs.tdwg.org/ltc/terms/preparationType]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."preservationMethod" IS 'A term used to classify or describe an object that indicates the primary or most recent action, measure or process that has been used in order to preserve the objects in the collection for long-term storage. [http://rs.tdwg.org/ltc/terms/preservationMethod]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."preservationMode" IS 'The means by which a palaeontological specimen was preserved or created e.g. body, cast, mold, trace fossil, soft parts mineralised etc. [http://rs.tdwg.org/ltc/terms/preservationMode]';
COMMENT ON COLUMN ltc_dp_collapsed.object_group."typeOfObjectGroup" IS 'Additional information that describes the object(s) in the collection. [http://rs.tdwg.org/ltc/terms/typeOfObjectGroup]';

-- Organisational Unit: A unit within an organisational hierarchy which may be at, above or below the institutional level.
CREATE TABLE ltc_dp_collapsed.organisational_unit (
    "organisationalUnit_pk" text NOT NULL,
    "objectGroup_fk" text NOT NULL,
    "parentOrganisationalUnit_fk" text NOT NULL,
    "organisationalUnitName" text NOT NULL,
    "organisationalUnitType" text NOT NULL,
    CONSTRAINT organisational_unit_pkey PRIMARY KEY ("organisationalUnit_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.organisational_unit IS 'A unit within an organisational hierarchy which may be at, above or below the institutional level. [http://rs.tdwg.org/ltc/terms/OrganisationalUnit]';
COMMENT ON COLUMN ltc_dp_collapsed.organisational_unit."organisationalUnit_pk" IS 'A unique identifier for an ltc:OrganisationalUnit. [http://example.com/term-pending/organisationalUnitID]';
COMMENT ON COLUMN ltc_dp_collapsed.organisational_unit."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasOrganisationalUnit]';
COMMENT ON COLUMN ltc_dp_collapsed.organisational_unit."parentOrganisationalUnit_fk" IS 'An identifier for an ltc:OrganisationalUnit. [http://rs.tdwg.org/ltc/terms/hasParentOrganisationalUnit]';
COMMENT ON COLUMN ltc_dp_collapsed.organisational_unit."organisationalUnitName" IS 'An official name of the organisational unit in the local language. [http://rs.tdwg.org/ltc/terms/organisationalUnitName]';
COMMENT ON COLUMN ltc_dp_collapsed.organisational_unit."organisationalUnitType" IS 'The type or level of organisational unit within a hierarchy responsible for the management of the collection being described. [http://rs.tdwg.org/ltc/terms/organisationalUnitType]';

-- Person: A person (alive, dead, undead, or fictional).
CREATE TABLE ltc_dp_collapsed.person (
    "person_pk" text NOT NULL,
    "additionalName" text,
    "familyName" text,
    "fullName" text,
    "givenName" text,
    CONSTRAINT person_pkey PRIMARY KEY ("person_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.person IS 'A person (alive, dead, undead, or fictional). [http://rs.tdwg.org/ltc/terms/Person]';
COMMENT ON COLUMN ltc_dp_collapsed.person."person_pk" IS 'A unique identifier for an ltc:Person. [http://example.com/term-pending/personID]';
COMMENT ON COLUMN ltc_dp_collapsed.person."additionalName" IS 'An additional name for a Person, can be used for a middle name. [https://schema.org/additionalName]';
COMMENT ON COLUMN ltc_dp_collapsed.person."familyName" IS 'Family name. In the U.S., the last name of a Person. [https://schema.org/familyName]';
COMMENT ON COLUMN ltc_dp_collapsed.person."fullName" IS 'String of the preferred form of personal name for displaying. [http://rs.tdwg.org/abcd/terms/fullName]';
COMMENT ON COLUMN ltc_dp_collapsed.person."givenName" IS 'Given name. In the U.S., the first name of a Person. [https://schema.org/givenName]';

-- Person Role: A qualified association between a Person or OrganisationalUnit and an entity such as an ObjectGroup or MeasurementOrFact that enables the relationship to be contextualised with a specific role and time period.
CREATE TABLE ltc_dp_collapsed.person_role (
    "personRole_pk" text NOT NULL,
    "person_fk" text NOT NULL,
    "role_fk" text NOT NULL,
    "event_fk" text,
    "objectGroup_fk" text,
    "organisationalUnit_fk" text,
    "recordLevel_fk" text,
    CONSTRAINT person_role_pkey PRIMARY KEY ("personRole_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.person_role IS 'A qualified association between a Person or OrganisationalUnit and an entity such as an ObjectGroup or MeasurementOrFact that enables the relationship to be contextualised with a specific role and time period. [http://rs.tdwg.org/ltc/terms/PersonRole]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."personRole_pk" IS 'A unique identifier for an ltc:PersonRole. [http://example.com/term-pending/personRoleID]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."person_fk" IS 'An identifier for an ltc:Person. [http://rs.tdwg.org/ltc/terms/hasPerson]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."role_fk" IS 'An identifier for an ltc:Role. [http://rs.tdwg.org/ltc/terms/hasRole]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."event_fk" IS 'An identifier for an ltc:Event. [http://rs.tdwg.org/ltc/terms/hasPersonRole]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasPersonRole]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."organisationalUnit_fk" IS 'An identifier for an ltc:OrganisationalUnit. [http://rs.tdwg.org/ltc/terms/hasPersonRole]';
COMMENT ON COLUMN ltc_dp_collapsed.person_role."recordLevel_fk" IS 'An identifier for an ltc:RecordLevel. [http://rs.tdwg.org/ltc/terms/hasPersonRole]';

-- Record Level: The machine-actionable information profile for the collection description digital object.
CREATE TABLE ltc_dp_collapsed.record_level (
    "recordLevel_pk" text NOT NULL,
    "isDerivedCollection" boolean,
    "license" text NOT NULL,
    "rights" text,
    "rightsHolder" text,
    CONSTRAINT record_level_pkey PRIMARY KEY ("recordLevel_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.record_level IS 'The machine-actionable information profile for the collection description digital object. [http://rs.tdwg.org/ltc/terms/RecordLevel]';
COMMENT ON COLUMN ltc_dp_collapsed.record_level."recordLevel_pk" IS 'A unique identifier for an ltc:RecordLevel. [http://example.com/term-pending/recordLevelID]';
COMMENT ON COLUMN ltc_dp_collapsed.record_level."isDerivedCollection" IS 'A flag to indicate that the collection description has been generated by aggregating data from one or more underlying datasets of its individual objects. [http://rs.tdwg.org/ltc/terms/isDerivedCollection]';
COMMENT ON COLUMN ltc_dp_collapsed.record_level."license" IS 'A legal document giving official permission to do something with the resource. [http://purl.org/dc/terms/license]';
