-- Resource Relationship: A relationship of one rdfs:Resource (http://www.w3.org/2000/01/rdf-schema#Resource) to another, or to a simple named concept.
CREATE TABLE ltc_dp_collapsed.resource_relationship (
    "resourceRelationship_pk" text NOT NULL,
    "objectGroup_fk" text,
    "recordLevel_fk" text,
    "relatedResourceID" text,
    "relatedResourceName" text,
    "relatedResourceType" text,
    "relationshipAccordingTo" text[],
    "relationshipEstablishedDate" text,
    "relationshipOfResource" text NOT NULL,
    "relationshipRemarks" text,
    "resourceID" text NOT NULL,
    CONSTRAINT resource_relationship_pkey PRIMARY KEY ("resourceRelationship_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.resource_relationship IS 'A relationship of one rdfs:Resource (http://www.w3.org/2000/01/rdf-schema#Resource) to another, or to a simple named concept. [http://rs.tdwg.org/ltc/terms/ResourceRelationship]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."resourceRelationship_pk" IS 'A unique identifier for an ltc:ResourceRelationship. [http://example.com/term-pending/resourceRelationshipID]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasResourceRelationship]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."recordLevel_fk" IS 'An identifier for an ltc:RecordLevel. [http://rs.tdwg.org/ltc/terms/hasResourceRelationship]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relatedResourceID" IS 'An identifier for a related resource (the object, rather than the subject of the relationship). [http://rs.tdwg.org/dwc/terms/relatedResourceID]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relatedResourceName" IS 'A short textual name for the related resource. [http://rs.tdwg.org/ltc/terms/relatedResourceName]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relatedResourceType" IS 'The class or property within Latimer Core, or class, property or less formal concept outside of the Latimer Core standard, that is represented by the related resource. [http://example.com/term-pending/relatedResourceType]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relationshipAccordingTo" IS 'The source (person, organization, publication, reference) establishing the relationship between the two resources. [http://rs.tdwg.org/dwc/terms/relationshipAccordingTo]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relationshipEstablishedDate" IS 'The date-time on which the relationship between the two resources was established. [http://rs.tdwg.org/dwc/terms/relationshipEstablishedDate]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relationshipOfResource" IS 'The relationship of the resource identified by relatedResourceID to the subject (optionally identified by the resourceID). [http://rs.tdwg.org/ltc/terms/relationshipOfResource]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."relationshipRemarks" IS 'Comments or notes about the relationship between the two resources. [http://rs.tdwg.org/dwc/terms/relationshipRemarks]';
COMMENT ON COLUMN ltc_dp_collapsed.resource_relationship."resourceID" IS 'An identifier for the resource that is the subject of the relationship. [http://rs.tdwg.org/dwc/terms/resourceID]';

