COMMENT ON COLUMN ltc_dp_collapsed.scheme_measurement_or_fact."isRepeatableMetric" IS 'A flag to designate whether multiple instances of the same schemeMeasurementType may be attached to a single entity. [http://rs.tdwg.org/ltc/terms/isRepeatableMetric]';
COMMENT ON COLUMN ltc_dp_collapsed.scheme_measurement_or_fact."schemeMeasurementType" IS 'A category of quantitative metric or qualitative fact that can be included in the LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/schemeMeasurementType]';

-- Scheme Term: A Latimer Core term used by the LatimerCoreScheme and the rules relating to its application.
CREATE TABLE ltc_dp_collapsed.scheme_term (
    "schemeTerm_pk" text NOT NULL,
    "latimerCoreScheme_fk" text NOT NULL,
    "isMandatoryTerm" boolean NOT NULL,
    "isRepeatableTerm" boolean NOT NULL,
    "termName" text NOT NULL,
    CONSTRAINT scheme_term_pkey PRIMARY KEY ("schemeTerm_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.scheme_term IS 'A Latimer Core term used by the LatimerCoreScheme and the rules relating to its application. [http://rs.tdwg.org/ltc/terms/SchemeTerm]';
COMMENT ON COLUMN ltc_dp_collapsed.scheme_term."schemeTerm_pk" IS 'A unique identifier for an ltc:SchemeTerm. [http://example.com/term-pending/schemeTermID]';
COMMENT ON COLUMN ltc_dp_collapsed.scheme_term."latimerCoreScheme_fk" IS 'An identifier for an ltc:LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/hasSchemeTerm]';
COMMENT ON COLUMN ltc_dp_collapsed.scheme_term."isMandatoryTerm" IS 'A flag to designate whether it is mandatory or optional for all ObjectGroups in the LatimerCoreScheme to include or be linked to valid data for the class or property defined in the termName property. [http://rs.tdwg.org/ltc/terms/isMandatoryTerm]';
COMMENT ON COLUMN ltc_dp_collapsed.scheme_term."isRepeatableTerm" IS 'A flag to designate whether multiple instances of the Latimer Core class or property defined in the termName property may be attached to a single ObjectGroup. [http://rs.tdwg.org/ltc/terms/isRepeatableTerm]';
COMMENT ON COLUMN ltc_dp_collapsed.scheme_term."termName" IS 'The name of a class or property within the Latimer Core standard that is included in the LatimerCoreScheme. [http://rs.tdwg.org/ltc/terms/termName]';

-- Storage Location: A physical location (such as a building, room, cabinet or drawer) within the holding institution where objects associated with the collection description are stored or exhibited.
CREATE TABLE ltc_dp_collapsed.storage_location (
