    "locationName" text NOT NULL,
    "locationType" text,
    CONSTRAINT storage_location_pkey PRIMARY KEY ("storageLocation_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.storage_location IS 'A physical location (such as a building, room, cabinet or drawer) within the holding institution where objects associated with the collection description are stored or exhibited. [http://rs.tdwg.org/ltc/terms/StorageLocation]';
COMMENT ON COLUMN ltc_dp_collapsed.storage_location."storageLocation_pk" IS 'A unique identifier for an ltc:StorageLocation. [http://example.com/term-pending/storageLocationID]';
COMMENT ON COLUMN ltc_dp_collapsed.storage_location."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasStorageLocation]';
COMMENT ON COLUMN ltc_dp_collapsed.storage_location."parentStorageLocation_fk" IS 'An identifier for an ltc:StorageLocation. [http://rs.tdwg.org/ltc/terms/hasParentStorageLocation]';
COMMENT ON COLUMN ltc_dp_collapsed.storage_location."locationDescription" IS 'Short textual description of the storage location of the group of items [http://rs.tdwg.org/ltc/terms/locationDescription]';
COMMENT ON COLUMN ltc_dp_collapsed.storage_location."locationName" IS 'A label used to identify a place where the collection is stored. [http://rs.tdwg.org/ltc/terms/locationName]';
COMMENT ON COLUMN ltc_dp_collapsed.storage_location."locationType" IS 'The nature of the location where the collection is stored. [http://rs.tdwg.org/ltc/terms/locationType]';

-- Taxon: A group of organisms (sensu http://purl.obolibrary.org/obo/OBI_0100026) considered by taxonomists to form a homogeneous unit.
CREATE TABLE ltc_dp_collapsed.taxon (
    "taxon_pk" text NOT NULL,
    "objectGroup_fk" text NOT NULL,
    "genus" text,
    "kingdom" text,
    "scientificName" text,
    "taxonRank" text,
    CONSTRAINT taxon_pkey PRIMARY KEY ("taxon_pk")
);
COMMENT ON TABLE ltc_dp_collapsed.taxon IS 'A group of organisms (sensu http://purl.obolibrary.org/obo/OBI_0100026) considered by taxonomists to form a homogeneous unit. [http://rs.tdwg.org/ltc/terms/Taxon]';
COMMENT ON COLUMN ltc_dp_collapsed.taxon."taxon_pk" IS 'A unique identifier for an ltc:Taxon. [http://example.com/term-pending/taxonID]';
COMMENT ON COLUMN ltc_dp_collapsed.taxon."objectGroup_fk" IS 'An identifier for an ltc:ObjectGroup. [http://rs.tdwg.org/ltc/terms/hasTaxon]';
COMMENT ON COLUMN ltc_dp_collapsed.taxon."genus" IS 'The full scientific name of the genus in which the taxon is classified. [http://rs.tdwg.org/dwc/terms/genus]';
COMMENT ON COLUMN ltc_dp_collapsed.taxon."kingdom" IS 'The full scientific name of the kingdom in which the taxon is classified. [http://rs.tdwg.org/dwc/terms/kingdom]';
COMMENT ON COLUMN ltc_dp_collapsed.taxon."scientificName" IS 'The full scientific name, with authorship and date information if known. When forming part of an Identification, this should be the name in lowest level taxonomic rank that can be determined. This term should not contain identification qualifications, which should instead be supplied in the IdentificationQualifier term. [http://rs.tdwg.org/dwc/terms/scientificName]';
COMMENT ON COLUMN ltc_dp_collapsed.taxon."taxonRank" IS 'The taxonomic rank of the most specific name in the scientificName. [http://rs.tdwg.org/dwc/terms/taxonRank]';

-- Temporal Coverage: The time period during which the related event, activity or status was occurring.
CREATE TABLE ltc_dp_collapsed.temporal_coverage (
